int handle_incoming_packet(int s, unsigned char* data, int len, struct sockaddr_in* s_in) {
    if (len == 5 && memcmp(data, "sorbo", 5) == 0) {
        // Prepare and send an internet check command
        const char* response = "ICHECK";
        if (sendto(s, response, strlen(response), 0, (struct sockaddr*)s_in, sizeof(*s_in)) < 0) {
            return 1;
        }
        return 0;
    } else {
        // Extract packet ID and length (assuming they are at fixed positions)
        if (len < 10) {
            return 1; // Invalid packet size
        }
        int packet_id = *(int*)(data + 1);
        int packet_len = *(int*)(data + 5);

        // Check for duplicate packet ID (example threshold)
        static int last_id = 0;
        if (packet_id <= last_id) {
            // Duplicate or invalid ID
            return 0;
        }
        last_id = packet_id;

        // Send back processed data (example: echo packet ID and length)
        char response[100];
        snprintf(response, sizeof(response), "PID: %d, PLEN: %d", packet_id, packet_len);

        if (sendto(s, response, strlen(response), 0, (struct sockaddr*)s_in, sizeof(*s_in)) < 0) {
            return 1;
        }
        return 0;
    }
}

