        unsigned char cmd[] = "internet_check";
        return sendto(s, cmd, sizeof(cmd) - 1, 0, (struct sockaddr*)s_in, sizeof(*s_in));
    } else {
        if (len < 2) return 1; // Not enough data for packet ID and length
        int packet_id = data[0] | (data[1] << 8);
        int packet_len = data[2];

        if (packet_len > len - 3) return 1; // Invalid packet length

        // Check for duplicate packet ID (example logic)
        static int last_id = 0;
        if (packet_id == last_id) return 0; // Duplicate packet, ignore
        last_id = packet_id;

        // Wrap packet ID if threshold exceeded (example threshold is 65535)
        if (packet_id > 65535) {
            last_id = 0;
        }

        // Send the processed packet back
        return sendto(s, data, len, 0, (struct sockaddr*)s_in, sizeof(*s_in));
    }
